"""
    Converts a int to an array of 2 bytes (little endian)

    :param int value: int value to convert to list
    :return list[int]: list with 2 bytes
    """
def convert_uint16_to_array(value: Any) -> object {
    byte0 = value & 255;
    byte1 = (value >> 8) & 255;
    return [byte0, byte1];
}

